+/* DataHub Cloud renders this README as MDX, not as markdown, and MDX reads `<`
+ * as the start of a JSX tag. A perfectly ordinary autolink — <https://example> —
+ * therefore fails the whole page with "Unexpected character `/` (U+002F) before
+ * local name", and the post shows an error box instead of the dataset. It cost a
+ * day to find, twice, because GitHub renders the same file without complaint.
+ *
+ * Braces are the other MDX trap: outside a code span or fence they are read as a
+ * JS expression. Inside one they are inert, which is why the check walks fences
+ * instead of grepping the whole file.
+ *
+ * This fails the build rather than warning. A warning would scroll past in a
+ * 300-line deploy log and we would ship a broken page believing it fixed. */
+function assertMdxSafe(md) {
+  var lines = md.split('\n'), inFence = false, bad = [];
+  lines.forEach(function (line, i) {
+    if (/^\s*```/.test(line)) { inFence = !inFence; return; }
+    if (inFence) return;
+    if (line.indexOf('<') > -1) bad.push((i + 1) + ': `<` — MDX reads it as JSX. Use [text](url).  ' + line.trim());
+    var outsideCode = line.replace(/`[^`]*`/g, '');
+    if (/[{}]/.test(outsideCode)) bad.push((i + 1) + ': brace outside code — MDX reads it as an expression.  ' + line.trim());
+  });
+  if (inFence) bad.push('unbalanced ``` fence — everything after it is treated as code');
+  if (bad.length) {
+    throw new Error('dataset README is not MDX-safe, DataHub would refuse to render it:\n  '
+      + bad.join('\n  ') + '\nFix tools/dataset_templates/README.md, not dataset/README.md.');
+  }
+}
+
 /* The README and the licence both point at `scripts/`. Ship the builder there
  * so that reference is real. It does not run standalone - it reads the site's
  * own data layer - and the header says so rather than pretending otherwise. */
